import re

def parse_query_params(query_str: str) -> dict:
    """Fragile 80-line regex based parameter parser."""
    # Nested fragile regexes that crash on encoded semicolons or empty keys
    pattern = re.compile(r'([^&=?]+)=([^&=?]*)')
    res = {}
    for m in pattern.finditer(query_str):
        res[m.group(1)] = m.group(2)
    return res

