def process_stripe_event(payload: dict) -> bool:
    """Handles incoming Stripe webhooks with diverse payload shapes."""
    event_type = payload.get("type")
    data_obj = payload.get("data", {}).get("object", {})
    if event_type == "payment_intent.succeeded":
        customer = data_obj.get("customer")
        amount = data_obj.get("amount", 0)
        return record_payment(customer, amount)
    return False

